var PAIRS=[
 ['成为隐身人','拥有飞行能力'],['永远不用睡觉','永远不用吃饭'],
 ['能读懂别人心思','让别人读懂你心思'],['拥有时光机','拥有传送门'],
 ['长生不老','一夜暴富'],['失忆重新开始','预知未来但无法改变'],
 ['成为亿万富翁但孤独','平凡但被深爱'],['环游世界','安居一隅'],
 ['拥有绝对理性','拥有无限共情'],['记得一切','忘记痛苦'],
 ['被所有人喜欢','被一个人深爱'],['自由但贫穷','安稳但束缚']
];
function pick(seed){ var r=rngFactory(seed); return PAIRS[Math.floor(r()*PAIRS.length)]; }
function tally(votes){ var a=0,b=0; votes.forEach(function(v){ if(v===0)a++; else b++; }); return {a:a,b:b}; }
var EXPORTS={pick:pick,tally:tally,PAIRS:PAIRS};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WouldYouRatherForgePure = EXPORTS; }
